import 'package:cloud_firestore/cloud_firestore.dart';
import 'app_enums.dart';
import 'model_utils.dart';
class AppointmentModel { const AppointmentModel({required this.id,required this.advisorId,required this.startsAt,required this.endsAt,required this.status,this.studentId,this.consultationId}); final String id,advisorId; final DateTime startsAt,endsAt; final AppointmentStatus status; final String? studentId,consultationId; factory AppointmentModel.fromFirestore(DocumentSnapshot<Map<String,Object?>> d)=>AppointmentModel(id:d.id,advisorId:d['advisorId'] as String,startsAt:dateFromValue(d['startsAt'])!,endsAt:dateFromValue(d['endsAt'])!,status:AppointmentStatus.values.byName(d['status'] as String),studentId:d['studentId'] as String?,consultationId:d['consultationId'] as String?); Map<String,Object?> toFirestore()=>{'advisorId':advisorId,'startsAt':Timestamp.fromDate(startsAt),'endsAt':Timestamp.fromDate(endsAt),'status':status.value,'studentId':studentId,'consultationId':consultationId}; }
